INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 1, 'Samsung T7 500GB', 'samsung-t7-500gb', 'MU-PC500S', 'B0874XM4SD', 'Samsung T7', 500, 'External', 'USB 3.2 Gen 2', 1050, 1000, 300, 3, 'The base T7 is the SSD most people should buy — a pocket-sized aluminum slab that delivers the full 10Gbps USB experience without a rugged premium. Its understated metal body doubles as a heatsink, keeping sustained writes pegged at 1000 MB/s even on long 50GB+ transfers.', NULL, '["Full 1050/1000 MB/s over USB 3.2 Gen 2","Compact aluminum body acts as heatsink","AES 256-bit hardware encryption included","Broad device compatibility (PC, Mac, console, phone)"]', '["No IP rating — not dust/water resistant","Plastic top plate scratches easily","Slower than Gen 2x2 rivals at the same price"]', 9.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 1, 'Samsung T7 1TB', 'samsung-t7-1tb', 'MU-PC1T0S', 'B0874XN4D8', 'Samsung T7', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 3, 'The 1TB T7 is the value sweet spot of Samsung''s portable line — big enough for a working photo/video library, fast enough for direct 4K ProRes editing, and still small enough to live in a jacket pocket. The aluminum chassis keeps the drive cool under sustained workloads that throttle lesser plastic-bodied drives.', NULL, '["Full 1050/1000 MB/s sustained","Cool-running aluminum chassis","AES 256-bit hardware encryption","Cheapest per-TB of the T7 family"]', '["No IP rating for field use","Write speed drops on transfers over 200GB if ambient is hot","Cable included is USB-C to C only"]', 9.2, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 1, 'Samsung T7 2TB', 'samsung-t7-2tb', 'MU-PC2T0S', 'B0874XM4SD', 'Samsung T7', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'The 2TB T7 holds a full MacBook worth of media without flinching — sustained writes on the 2TB die stack stay pegged at 1000 MB/s well past the 200GB mark where 1TB T7 starts to taper. A sensible growth choice for creators outgrowing 1TB.', NULL, '["Sustained writes hold 1000 MB/s past 200GB","Cool operation under load","Hardware encryption included","Lower cost per TB than the 1TB"]', '["No IP rating","Cable is USB-C only — Mac users need a C-to-A","Plastic top shows scratches"]', 9.3, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 1, 'Samsung T7 4TB', 'samsung-t7-4tb', 'MU-PC4T0S', 'B08S2BYTM7', 'Samsung T7', 4000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 2400, 3, 'The 4TB T7 is the largest single-drive external storage most people can buy without moving to a wall-powered Thunderbolt desktop enclosure. Perfect for moving a desktop-grade media library between office, home, and field shoots.', NULL, '["4TB of pocket storage","Stays cool under sustained loads","Hardware encryption","Best $/TB of the T7 line once on sale"]', '["No IP rating","Heavy for the T7 family","Bundled C-to-C cable is short"]', 9.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 1, 'Samsung T7 Touch 1TB', 'samsung-t7-touch-1tb', 'MU-PC1T0K', 'B0874W8FXF', 'Samsung T7 Touch', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 3, 'A T7 with a fingerprint reader where most drives put a status LED — the Touch unlocks encrypted volumes without typing a password. It''s the rare security-focused portable drive that doesn''t make security annoying to use.', NULL, '["Fingerprint unlock — no password typing","Full 1050/1000 MB/s speeds","Cool-running metal body","Three fingerprints supported"]', '["Fingerprint setup is desktop-only","No IP rating","Premium pricing vs base T7","LED strip is polarizing aesthetics"]', 8.8, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 1, 'Samsung T7 Touch 2TB', 'samsung-t7-touch-2tb', 'MU-PC2T0K', 'B089GVGDGD', 'Samsung T7 Touch', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'Same fingerprint-equipped T7 Touch with twice the die stack — sustained writes stay pegged at 1000 MB/s well past 200GB on the 2TB. A solid choice if you want one-touch unlock on a drive big enough to back up a whole laptop.', NULL, '["2TB capacity","Fingerprint unlock","Sustained writes stay pegged","Hardware encryption fallback"]', '["Setup software is desktop-only","Premium over base T7","C-to-C cable only","No IP rating"]', 8.9, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 1, 'Samsung T7 Shield 2TB', 'samsung-t7-shield-2tb', 'MU-PE2T0S', 'B09V7KTMFH', 'Samsung T7 Shield', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'The middle of the T7 Shield line — 2TB of IP65 rugged storage that takes a 3-meter drop onto concrete and keeps the rain out. The sweet spot for outdoor photo shoots, drone-field offloads, and any travel workflow where a non-rugged drive would die in a year.', NULL, '["IP65 dust and water resistant","3-meter drop rated","1050/1000 MB/s full speed","Aluminum core inside rubber shell"]', '["Rubber exterior collects lint","No Gen 2x2 speeds","Heavier than base T7","No USB-A cable in box"]', 9.3, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 1, 'Samsung T9 2TB', 'samsung-t9-2tb', 'MU-PD2T0S', 'B0CHFSMWHK', 'Samsung T9', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 5, 'The 2TB T9 doubles the write endurance of the 1TB while keeping the full 20Gbps Gen 2x2 link. The right size for working 6K Blackmagic RAW footage in the field — sustained 2 GB/s means editing directly off the drive is indistinguishable from internal storage.', NULL, '["Full 2000/2000 MB/s over Gen 2x2","5-year warranty","Sustained write holds past 300GB","Ridiculously small for the speed"]', '["Needs USB 3.2 Gen 2x2 host to exceed T7 speeds","Premium price per TB","No AES hardware encryption"]', 9.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 4, 'SanDisk Extreme Pro Portable 1TB', 'sandisk-extreme-pro-portable-1tb', 'SDSSDE61-1T00', 'B08GV9M64L', 'SanDisk Extreme Pro', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 5, 'A 1050 MB/s portable SSD in an aluminum-and-rubber body with an IP55 dust/water rating. The Extreme Pro is the ruggedized competitor to the Samsung T7 Shield — headlining a 5-year warranty where Samsung offers 3, and including both USB-C-to-C and USB-C-to-A cables.', NULL, '["IP55 dust and water resistant","Aluminum chassis with rubber bumper","5-year warranty","Both USB-C and USB-A cables included"]', '["Slower sustained writes than T7 in some workloads","Rubber bumper not removable","Game-loading support inconsistent on PS5"]', 9.1, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 4, 'SanDisk Extreme Pro Portable 2TB', 'sandisk-extreme-pro-portable-2tb', 'SDSSDE61-2T00', 'B08GV9QM8R', 'SanDisk Extreme Pro', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 5, 'The 2TB Extreme Pro is where SanDisk''s ruggedization meets real-world capacity — enough room for a 4K video project, full Lightroom catalog, and Time Machine backup simultaneously. The IP55 shell handles trail dust and light rain where the T7 would not.', NULL, '["IP55 rugged body","5-year warranty","Both cables in box","Faster sustained 2TB writes than 1TB version"]', '["Rubber collects pocket lint","Inconsistent write speed under thermal load","Premium pricing vs non-rugged peers"]', 9.2, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 4, 'SanDisk Extreme Portable 1TB', 'sandisk-extreme-portable-1tb', 'SDSSDE61-1T00-G25', 'B08GTYFC37', 'SanDisk Extreme', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 3, 'The non-Pro Extreme is the lower-cost sibling — same 1050 MB/s rated read and IP55 rugged body, but writes top out well below Extreme Pro on sustained workloads. A solid buy when the write-speed gap doesn''t matter (game consoles, file transfer, backup) but the rugged rating does.', NULL, '["IP55 rugged body","Same 1050 read as Extreme Pro","Cheaper than Pro by a wide margin","USB-A cable included"]', '["Sustained writes drop after SLC cache fills","3-year warranty vs Pro''s 5-year","Write speeds much slower than rated on long transfers"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 4, 'SanDisk Extreme Portable 2TB', 'sandisk-extreme-portable-2tb', 'SDSSDE61-2T00-G25', 'B08PG2M6VK', 'SanDisk Extreme', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'A cheaper alternative to the 2TB Extreme Pro for buyers who need capacity and ruggedization more than sustained write speed. The 2TB die stack actually sustains writes longer than the 1TB before the SLC cache exhausts.', NULL, '["IP55 rugged body","2TB storage","Lower cost than 2TB Extreme Pro","Both cables in box"]', '["Sustained writes drop after cache","3-year warranty","Slower than rated on long writes"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 2, 'Crucial X9 Pro 1TB', 'crucial-x9-pro-1tb', 'CT1000X9PROSSD9', 'B0C9WKGXH9', 'Crucial X9 Pro', 1000, 'External', 'USB 3.2 Gen 2', 1050, 950, 600, 5, 'A 1050 MB/s portable SSD for creators who need TLC NAND, hardware encryption, and a 5-year warranty at less than Extreme Pro prices. The X9 Pro is Crucial''s premium Gen 2 line — it targets direct-edit workflows where sustained writes and write endurance matter more than headline speeds.', NULL, '["Real TLC NAND (not QLC)","5-year warranty","AES 256-bit hardware encryption","Tiny aluminum unibody"]', '["No IP rating","Sustained writes dip below 950 MB/s after 100GB cache fill","USB-C cable only"]', 9.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 2, 'Crucial X9 Pro 2TB', 'crucial-x9-pro-2tb', 'CT2000X9PROSSD9', 'B0C9WKQFY7', 'Crucial X9 Pro', 2000, 'External', 'USB 3.2 Gen 2', 1050, 950, 1200, 5, 'The 2TB X9 Pro keeps the same sustained-write profile as the 1TB but with double the cache budget before throttle. A cost-effective workhorse drive for anyone editing directly off external storage.', NULL, '["Real TLC NAND","5-year warranty","Doubles sustained-write cache size","Hardware encryption"]', '["No IP rating","C-to-C cable only","Premium vs Samsung T7 2TB"]', 9.1, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 2, 'Crucial X10 Pro 2TB', 'crucial-x10-pro-2tb', 'CT2000X10PROSSD9', 'B0C9WJL63B', 'Crucial X10 Pro', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 5, 'The 2TB X10 Pro takes advantage of Gen 2x2 hosts but falls back gracefully on Gen 2 to 10 Gbps. A safe long-horizon buy — even if your current laptop only has Gen 2, you''ll see 2000 MB/s the day you upgrade to a Gen 2x2 host. Same TLC NAND, 5-year warranty, and encryption as the X9 Pro.', NULL, '["2000/2000 MB/s on Gen 2x2 hosts","5-year warranty","Hardware encryption","TLC NAND with full 1200 TBW"]', '["Only useful above T7 speeds if your host is Gen 2x2","Premium pricing","C-to-C cable only"]', 9.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 2, 'Crucial X6 1TB', 'crucial-x6-1tb', 'CT1000X6SSD9', 'B0CL5ZB4WR', 'Crucial X6', 1000, 'External', 'USB 3.2 Gen 2', 800, 800, 600, 3, 'The X6 is Crucial''s budget Gen 2 line — half the speed of the X9 Pro at typically half the price. A sensible choice for game-library expansion on PS5/Xbox or as a Time Machine drive, where sustained write speed matters far less than capacity-per-dollar.', NULL, '["800 MB/s over Gen 2","Cheapest per-TB of Crucial''s portable line","Compatible with PS5/Xbox expandable storage","Lightweight plastic body"]', '["Plastic body — no ruggedization","3-year warranty","800 MB/s cap is half of T7","No hardware encryption"]', 7.8, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 2, 'Crucial X6 2TB', 'crucial-x6-2tb', 'CT2000X6SSD9', 'B0CL5ZB68L', 'Crucial X6', 2000, 'External', 'USB 3.2 Gen 2', 800, 800, 1200, 3, 'The 2TB X6 is a budget buy for console-game storage or backup duty — at 800 MB/s it''s easily fast enough for cold-game library overflow on PS5 (where the internal SSD handles active play), and the larger die stack holds the 800 MB/s rate longer than the 1TB.', NULL, '["800 MB/s read","Budget-friendly $/TB","PS5/Xbox compatible for cold library","Cool under sustained load"]', '["No IP rating","No hardware encryption","3-year warranty","800 MB/s cap is half T7 speed"]', 8.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 2, 'Crucial X6 4TB', 'crucial-x6-4tb', 'CT4000X6SSD9', 'B0CL5ZBGD7', 'Crucial X6', 4000, 'External', 'USB 3.2 Gen 2', 800, 800, 2400, 3, 'A 4TB external at the X6''s price is closer to spinning-rust economics than to typical SSD pricing. The 800 MB/s cap doesn''t matter when the use case is video archive or photo-library cold storage — this drive is bought for capacity first, speed second.', NULL, '["4TB at budget-friendly price","PS5/Xbox cold-library compatible","Cool-running","3-year warranty"]', '["800 MB/s cap","No hardware encryption","Plastic body","No IP rating"]', 8.2, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 2, 'Crucial X8 1TB', 'crucial-x8-1tb', 'CT1000X8SSD9', 'B098FH7K96', 'Crucial X8', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 3, 'The X8 is Crucial''s older-gen premium aluminum portable — superseded in retail by the X9 Pro but often available steeply discounted. Same 1050/1000 MB/s speeds, same form factor, same aluminum body. A solid budget pick when sale-priced under the X9 Pro.', NULL, '["1050/1000 MB/s speeds","Anodized aluminum body","3-year warranty","Often on clearance pricing"]', '["Older generation (superseded by X9 Pro)","No hardware encryption","3-year (not 5) warranty","No IP rating"]', 8.3, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 2, 'Crucial X8 2TB', 'crucial-x8-2tb', 'CT2000X8SSD9', 'B098FH7KDR', 'Crucial X8', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'A 2TB solid-aluminum Crucial X8 — a previous-generation premium drive that often goes on clearance at discount retailers. Worth it when the price beats the equivalent X9 Pro by $30+.', NULL, '["Aluminum unibody","1050/1000 MB/s sustained","3-year warranty","Often available below X9 Pro pricing"]', '["Superseded by X9 Pro","No hardware encryption","No IP rating","C-to-C cable only"]', 8.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 3, 'WD My Passport SSD 2TB', 'wd-my-passport-ssd-2tb', 'WDBKVX0260BBK', 'B0874WWDJY', 'WD My Passport SSD', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'A 2TB WD My Passport SSD in the slim profile — 1050/1000 MB/s over USB-C with hardware encryption. The price-by-size math is competitive against the T7 family on sale, and the bundled software ( WD Discovery / Dashboard) is genuinely useful for diagnostics.', NULL, '["1050/1000 MB/s","256-bit AES hardware encryption","Slim metal-and-plastic body","Both USB-C and USB-A cables in box"]', '["Plastic top half feels cheap","WD Discovery required for encryption setup","3-year warranty only"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 3, 'WD My Passport SSD 4TB', 'wd-my-passport-ssd-4tb', 'WDBKVX0460BBK', 'B0B3Q5GT7S', 'WD My Passport SSD', 4000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 2400, 3, 'The 4TB My Passport SSD has a niche-of-one — the only 4TB USB-C portable from WD in this form factor. A viable T7 4TB competitor on sale, but check price moves against the Samsung before committing.', NULL, '["4TB in slim body","1050/1000 MB/s","Hardware encryption included","Both cables in box"]', '["3-year warranty vs Samsung''s 3","Sustained writes dip below 1000 after long SLC cache fills","Cable included is short"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 3, 3, 'WD Black P50 Game Drive SSD 1TB', 'wd-black-p50-1tb', 'WDBNAJ0010BBK', 'B07XNT5L7Q', 'WD Black P50', 1000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 600, 5, 'The WD Black P50 was the first console-targeted portable SSD to claim Gen 2x2 speeds on paper, although on a Gen 2 host it caps at 10Gbps. Big in Xbox/PS5 circles for the gamer-aesthetic naming and the 5-year warranty.', NULL, '["Gen 2x2 ready (2000 MB/s)","5-year warranty","Console-aesthetic build","Both cables in box"]', '["On Gen 2 hosts caps at 1050 MB/s","Sustained writes dip after cache","Larger footprint than T7"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 3, 3, 'WD Black P50 Game Drive SSD 2TB', 'wd-black-p50-2tb', 'WDBNAJ0020BBK', 'B07XNT5L7V', 'WD Black P50', 2000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 1200, 5, 'The 2TB Black P50 holds the 2000 MB/s write rate noticeably longer than the 1TB on long transfers. A natural choice for PS5 cold-library expansion where you want the extra cache budget for moving big installs.', NULL, '["Gen 2x2 ready","5-year warranty","2TB cold library for PS5","Both cables in box"]', '["Gen 2 cap is 1050 MB/s","Aesthetic is gamer-first","Larger than My Passport SSD"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 3, 3, 'WD Black P50 Game Drive SSD 4TB', 'wd-black-p50-4tb', 'WDBNAJ0040BBK', 'B0B5HH6TC9', 'WD Black P50', 4000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 2400, 5, 'A 4TB SSD explicitly marketed for PS5/Xbox Series X|S game-library cold storage — the entire point is moving games you''re not currently playing off the internal SSD without redownloading. Both cables in box, 5-year warranty.', NULL, '["4TB Gen 2x2 storage","5-year warranty","Both USB-C and USB-A cables","PS5/Xbox cold-library ready"]', '["Caps at 1050 MB/s on Gen 2 hosts","Premium pricing vs T7 4TB","Larger footprint"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 5, 'Seagate One Touch SSD 500GB', 'seagate-one-touch-ssd-500gb', 'STKS5000400', 'B08FS5L3HN', 'Seagate One Touch', 500, 'External', 'USB 3.2 Gen 2', 1030, 1030, 300, 3, 'The 500GB One Touch is Seagate''s entry-level portable SSD — typically the cheapest brand-name 1050-class Gen 2 drive at retail. Speeds are real-world faster than rated for short transfers; the catch is that the SLC cache is tiny.', NULL, '["1030 MB/s read","Cheapest brand-name Gen 2 SSD class","Both cables included","Three-year service plan with Rescue data recovery"]', '["SLC cache tiny — writes dip to ~400 MB/s after 50GB","3-year warranty","Plastic body","No encryption"]', 7.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 5, 'Seagate One Touch SSD 1TB', 'seagate-one-touch-ssd-1tb', 'STKS1000400', 'B08FS5NBQM', 'Seagate One Touch', 1000, 'External', 'USB 3.2 Gen 2', 1030, 1030, 600, 3, 'The 1TB One Touch is the realistic minimum for game-library cold storage and Time Machine backups under typical Seagate sale pricing. Three-year Rescue data-recovery plan included.', NULL, '["1030 MB/s read","Both USB-C and USB-A cables","Rescue data recovery plan","Often on sale well below T7 1TB price"]', '["Sustained writes dip after SLC cache fills","3-year warranty","No encryption on Windows","Plastic body"]', 7.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 5, 'Seagate One Touch SSD 2TB', 'seagate-one-touch-ssd-2tb', 'STKS2000400', 'B08FS5PYCQ', 'Seagate One Touch', 2000, 'External', 'USB 3.2 Gen 2', 1030, 1030, 1200, 3, 'The 2TB One Touch is the sweet spot of Seagate''s budget portable line — large enough die stack that the sustained-write dropoff after SLC exhaustion is significantly longer than on the 1TB.', NULL, '["1030 MB/s rated","Both cables in box","Rescue data recovery","Larger SLC cache than 1TB"]', '["Sustained writes still flag under heavy load","3-year warranty","Plastic body","No IP rating"]', 7.8, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 3, 5, 'Seagate FireCuda Gaming SSD 2TB', 'seagate-firecuda-gaming-2tb', 'STFS2000400', 'B0936BPJTV', 'Seagate FireCuda', 2000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 1200, 5, 'The 2TB FireCuda Gaming SSD is Seagate''s answer to the WD Black P50 — a Gen 2x2 portable marketed at console gamers with a 2000 MB/s rated speed and 5-year warranty. The RGB center strip lights up when in use; an included app can sync it with other Razer Chroma gear.', NULL, '["Gen 2x2 2000 MB/s","5-year warranty","RGB lighting","Both cables in box"]', '["RGB is polarizing","Caps at 1050 MB/s on Gen 2 hosts","Larger than T7","Premium pricing"]', 8.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 3, 5, 'Seagate FireCuda Gaming SSD 4TB', 'seagate-firecuda-gaming-4tb', 'STFS4000400', 'B09V1GZ6ZV', 'Seagate FireCuda', 4000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 2400, 5, 'The 4TB FireCuda is the biggest Seagate portable SSD — a Gen 2x2 RGB drive sized for entire game-library overflow. The 5-year warranty and included Rescue plan are real value-adds at this capacity.', NULL, '["4TB Gen 2x2 storage","5-year warranty + Rescue","RGB lighting","Console compatible for cold library"]', '["RGB unnecessary for non-gamers","Premium pricing vs 4TB T7","No IP rating for rugged use"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 2, 6, 'Sabrent Rocket XTRM-Q 2TB', 'sabrent-rocket-xtrm-q-2tb', 'SB-XTRM-Q-2TB', 'B0CD2TVQ9B', 'Sabrent Rocket Nano XTRM-Q', 2000, 'External', 'Thunderbolt 3', 2700, 2700, 1200, 3, 'The 2TB XTRM-Q is the model that put Sabrent''s portable Thunderbolt line on the map for Mac users who needed internal-class speeds in an external chassis. Like the 1TB, it dedicated to Thunderbolt 3/4 hosts — on USB only you''ll see Gen 2 speed (~1050 MB/s), not the headline 2700 MB/s.', NULL, '["Thunderbolt-class 2700 MB/s","Doubles capacity of base XTRM-Q","Cables included","5-year warranty (with registration)"]', '["Premium price","Looks like a Gen 2 drive on a USB-only host","Heavier than typical portable SSD"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 2, 6, 'Sabrent Rocket XTRM-Q 4TB', 'sabrent-rocket-xtrm-q-4tb', 'SB-XTRM-Q-4TB', 'B0DJWZV9CQ', 'Sabrent Rocket Nano XTRM-Q', 4000, 'External', 'Thunderbolt 3', 2700, 2700, 2400, 3, 'A 4TB Thunderbolt 3 portable SSD is genuinely rare — most vendors cap at 2TB. The 4TB XTRM-Q is the enthusiast-choice for working 8K RED RAW footage in the field. Price is high but for revenue-grade video work that needs the speed, nothing else at this capacity competes.', NULL, '["2700 MB/s Thunderbolt","4TB of high-speed storage","3-year manufacturer warranty","Aluminum heatsink body"]', '["Premium pricing","Requires Thunderbolt 3/4 host","Only worth it if you actively edit video"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 6, 'Sabrent Rocket Nano V2 1TB', 'sabrent-rocket-nano-v2-1tb', 'SB-NANO-V2-1TB', 'B0BN4J1994', 'Sabrent Rocket Nano V2', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 600, 3, 'A 2000 MB/s Gen 2x2 pocket drive with an aluminum unibody acting as a heatsink. The Nano V2 is one of the most compact Gen 2x2 drives available — fitting speed-and-thermal capacity that other vendors need bigger bodies to deliver.', NULL, '["2000/2000 MB/s on Gen 2x2","Aluminum unibody heatsink","Pocket-sized","USB-C cable included"]', '["Caps at 1050 MB/s on Gen 2 hosts","3-year warranty","Premium vs T7 1TB on non-2x2 hosts"]', 8.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 6, 'Sabrent Rocket Nano V2 2TB', 'sabrent-rocket-nano-v2-2tb', 'SB-NANO-V2-2TB', 'B0BN4JCKNW', 'Sabrent Rocket Nano V2', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 3, '2TB of Gen 2x2 storage in a pocketable aluminum unibody. Same form factor as the 1TB but with double the SLC cache budget, pushing sustained writes well past 300GB.', NULL, '["2000/2000 MB/s on Gen 2x2","Pocketable 2TB","Aluminum unibody","Same form factor as 1TB"]', '["Caps at 1050 MB/s on Gen 2 hosts","3-year warranty","Premium price"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 6, 'Sabrent Rocket Nano V2 4TB', 'sabrent-rocket-nano-v2-4tb', 'SB-NANO-V2-4TB', 'B0D5L5FXWC', 'Sabrent Rocket Nano V2', 4000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 2400, 3, 'The 4TB Rocket Nano V2 is unusually capacious for a Gen 2x2 portable — most 4TB portable SSDs ship at Gen 2 speeds. The trade-off is price, which is currently well above T7 4TB. Buy when you specifically need the Gen 2x2 link for fast offloads.', NULL, '["4TB Gen 2x2 storage","Aluminum unibody heatsink","2400 TBW endurance","Cool on sustained 2 GB/s workload"]', '["Premium pricing","Needs Gen 2x2 host above T7 speeds","3-year warranty"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 9, 'Corsair EX100U 2TB', 'corsair-ex100u-2tb', 'CSSD-EX100U-2TB', 'B0BGJ1JFKG', 'Corsair EX100U', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 1800, 1200, 3, 'A 2TB Gen 2x2 portable SSD in the same aluminum-and-rubber body as the 1TB. Write speed drops slightly to 1800 MB/s on the 2TB variant — a real-world trade-off for the larger NAND die. Still above 2GB/s on long transfers as long as the host is Gen 2x2.', NULL, '["Gen 2x2 speeds","2TB capacity","Both cables in box","Cool aluminum body"]', '["1800 MB/s (not 2000) on 2TB","3-year warranty","No IP rating","Premium vs T9 on Gen 2x2 hosts"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 9, 'Corsair EX400U 1TB', 'corsair-ex400u-1tb', 'CSSD-EX400U-1TB', 'B0DR379KSW', 'Corsair EX400U', 1000, 'External', 'USB4', 3300, 3000, 600, 5, 'A 1TB USB4 portable — 3300 MB/s read on a Thunderbolt 4 / USB4 host. The EX400U is the rare USB4 drive that supports the full 40Gbps link (not all USB4 drives do). 5-year warranty is best-in-class for the speed tier.', NULL, '["USB4 3300 MB/s read","5-year warranty","Full 40Gbps USB4 link","Console compatible"]', '["Only useful with USB4/Thunderbolt 4 host","Premium pricing","Cable is short","No IP rating"]', 9.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 2, 21, 'LaCie Rugged SSD Pro 1TB', 'lacie-rugged-ssd-pro-1tb', 'SPR900', 'B08FN34GWY', 'LaCie Rugged SSD Pro', 1000, 'External', 'Thunderbolt 3', 2700, 1900, 600, 5, 'A Thunderbolt 3 portable SSD in LaCie''s iconic orange-rubber bumpers — IP67, 3-meter drop, and 1-ton car-proof. The Rugged SSD Pro is the field-shoot standard for video crews who need one drive that survives a van rollover and still delivers Thunderbolt-class 2700 MB/s.', NULL, '["Thunderbolt 3 2700 MB/s","IP67 dust/water","3-meter drop + 1-ton crush","5-year Rescue included"]', '["Premium pricing","Bulky vs non-rugged peers","Orange bumper is polarizing","Cable integrated (replacement requires LaCie service)"]', 9.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 2, 21, 'LaCie Rugged SSD Pro 2TB', 'lacie-rugged-ssd-pro-2tb', 'SPR910', 'B08FN8WVG2', 'LaCie Rugged SSD Pro', 2000, 'External', 'Thunderbolt 3', 2700, 1900, 1200, 5, 'The 2TB Rugged SSD Pro doubles capacity of the iconic Thunderbolt 3 rugged drive. The standard field drive for outdoor wedding, extreme-sports, and news videographers who need both real-time 6K editing and a drive that survives a sandstorm.', NULL, '["Thunderbolt 3 2700 MB/s","IP67 rugged","5-year Rescue","Sustained writes stay pegged on 2TB stack"]', '["Premium pricing","Bulky","Integrated cable","Heavier than non-rugged peers"]', 9.1, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 2, 21, 'LaCie Rugged SSD Pro 4TB', 'lacie-rugged-ssd-pro-4tb', 'SPR920', 'B0B5DLLVMC', 'LaCie Rugged SSD Pro', 4000, 'External', 'Thunderbolt 3', 2700, 1900, 2400, 5, 'A 4TBThunderbolt 3 portable — uniquely huge for this speed tier. The Rugged SSD Pro 4TB fills a slot nothing else really does: 4TB of fast external storage that''s actually rugged, not just claimed to be.', NULL, '["Thunderbolt 3 + 4TB","IP67 + 3m drop + 1-ton crush","5-year Rescue","2400 TBW"]', '["Premium pricing","Bulky","Cable integrated","Premium over non-rugged 4TB portables"]', 9.2, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 21, 'LaCie Rugged SSD 1TB', 'lacie-rugged-ssd-1tb', 'LAC4000100', 'B08VG7VS7F', 'LaCie Rugged SSD', 1000, 'External', 'USB 3.2 Gen 2', 950, 950, 600, 5, 'The non-Pro Rugged SSD keeps the IP67 orange-rubber body but drops the Thunderbolt controller for USB 3.2 Gen 2. For photographers and documentarians whose laptops don''t have Thunderbolt anyway, this is the right compromise at a much lower price than the Pro.', NULL, '["IP67 rugged body","1050-class Gen 2 speeds","5-year warranty + Rescue","Detachable USB-C cable"]', '["950 MB/s — slower than full 1050","USB-C only","Premium over non-rugged SSDs","Bulky"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 21, 'LaCie Rugged SSD 2TB', 'lacie-rugged-ssd-2tb', 'LAC4000200', 'B08VG7Q41M', 'LaCie Rugged SSD', 2000, 'External', 'USB 3.2 Gen 2', 950, 950, 1200, 5, 'The 2TB non-Pro Rugged SSD keeps the orange armor but doubles the storage capacity. A common pick for outdoor photographers who shoot medium-format RAW and need the IP67 rating more than the Pro model''s Thunderbolt speeds.', NULL, '["2TB + IP67 rugged","1050-class Gen 2","5-year Rescue","Detachable USB-C cable"]', '["950 MB/s — slower than T7","Premium pricing","Bulkier than T7","USB-C only"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 8, 'Kingston XS2000 1TB', 'kingston-xs2000-1tb', 'SDSE2000/1TB', 'B09FB1P7LQ', 'Kingston XS2000', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 600, 5, 'A 2000 MB/s Gen 2x2 portable with a 5-year warranty — comparatively rare warranty term at Gen 2x2 pricing. Kingston claims a 2-meter drop rating but doesn''t list IP rating, putting it between rugged and non-rugged.', NULL, '["Gen 2x2 2000 MB/s","5-year warranty","2-meter drop rating","Detachable USB-C cable"]', '["No IP rating","Caps at 1050 on Gen 2 hosts","Premium pricing","Sustained writes dip after cache"]', 8.3, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 8, 'Kingston XS2000 2TB', 'kingston-xs2000-2tb', 'SDSE2000/2TB', 'B09FB1P7MX', 'Kingston XS2000', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 5, 'The 2TB XS2000 is a budget-grade Gen 2x2 portable with the same 5-year warranty as the 1TB but double the cache budget. Often the cheapest 2TB Gen 2x2 SSD at retail — a sensible budget alternative to the Sabrent or Samsung T9.', NULL, '["Gen 2x2 2000 MB/s","5-year warranty","2TB at aggressive price","Detachable USB-C cable"]', '["No IP rating","Plastic body","Slow sustained writes after cache","2-meter drop only"]', 8.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 8, 'Kingston XS2000 4TB', 'kingston-xs2000-4tb', 'SDSE2000/4TB', 'B09V3MJN32', 'Kingston XS2000', 4000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 2400, 5, 'The 4TB XS2000 is the budget king at this capacity — Kingston has priced it aggressively against the T9 and Sabrent since launch. If you need a Gen 2x2 4TB portable and the budget is tight, this is the price-floor drive to shortlist.', NULL, '["4TB Gen 2x2","5-year warranty","2400 TBW endurance","Detachable cable"]', '["No IP rating","Plastic body","Caps at 1050 MB/s on Gen 2 hosts","Conservative sustained write behavior"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 10, 'ADATA SE800 1TB', 'adata-se800-1tb', 'ASSE800-1TU32G2-C', 'B08GJKZQVT', 'ADATA SE800', 1000, 'External', 'USB 3.2 Gen 2', 1000, 950, 600, 3, 'A compact 1050-class Gen 2 portable at a budget price point. The SE800 is one of the cheapest brand-name 1TB external SSDs in retail — the cost-cutting shows in the plastic body and shorter warranty.', NULL, '["1000 MB/s read","Budget pricing","Tiny form factor","USB-C cable included"]', '["Plastic body","3-year warranty","950 MB/s write (not full 1050)","No IP rating"]', 7.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 10, 'ADATA SE800 2TB', 'adata-se800-2tb', 'ASSE800-2TU32G2-C', 'B08GJKYGCJ', 'ADATA SE800', 2000, 'External', 'USB 3.2 Gen 2', 1000, 950, 1200, 3, 'The 2TB SE800 keeps the same tiny plastic body of the 1TB and bumps the SLC cache budget. The budget-friendly per-TB makes it a viable choice for game-library cold storage where sustained write speed takes a back seat to capacity-per-dollar.', NULL, '["2TB at budget pricing","1000 MB/s read","Tiny form factor","USB-C cable included"]', '["Plastic body","3-year warranty","No IP rating","950 MB/s write"]', 7.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 10, 'ADATA Elite SE760 1TB', 'adata-elite-se760-1tb', 'ASSE760-1TU32G2-C', 'B08KJL7VKV', 'ADATA Elite SE760', 1000, 'External', 'USB 3.2 Gen 2', 1000, 900, 600, 3, 'The Elite SE760 is ADATA''s step-up from the SE800 — same Gen 2 1000 MB/s read but the body is metal rather than plastic, and the warranty term is identical at 3 years. Marginal upgrade; buy whichever is cheaper.', NULL, '["Metal body (vs SE800 plastic)","1000 MB/s read","Tiny profile","USB-C cable included"]', '["3-year warranty","950 MB/s write","No IP rating","Sluggish sustained writes after cache"]', 7.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 10, 'ADATA Elite SE760 2TB', 'adata-elite-se760-2tb', 'ASSE760-2TU32G2-C', 'B0B3G5WJQ9', 'ADATA Elite SE760', 2000, 'External', 'USB 3.2 Gen 2', 1000, 900, 1200, 3, 'The 2TB Elite SE760 keeps the metal body of the 1TB. Sustained writes on the 2TB die stack hold the rated 900 MB/s noticeably longer than the 1TB version, where the cache exhausts earlier.', NULL, '["Metal body","2TB capacity","1000 MB/s read","USB-C cable included"]', '["3-year warranty","900 MB/s write","No IP rating","Plastic-feel metal lid"]', 7.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 22, 'Patriot Evlvr 1TB', 'patriot-evlvr-1tb', 'PS2000', 'B07VXNCQCV', 'Patriot Evlvr', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 600, 3, 'A budget Gen 2x2 portable at a price that undercuts most rivals in the speed tier. The Evlvr has a no-frills aluminum body but no IP rating — clearly aimed at console-game cold library and PCIe 4 internal-SSD offload workflows.', NULL, '["Gen 2x2 2000 MB/s","Budget pricing","Aluminum body","USB-C cable included"]', '["3-year warranty","No IP rating","Caps at 1050 on Gen 2 hosts","Sustained writes dip after 100GB cache"]', 7.9, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 22, 'Patriot Evlvr 2TB', 'patriot-evlvr-2tb', 'PS2002', 'B07VXNCF9L', 'Patriot Evlvr', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 3, 'The 2TB Evlvr doubles the SLC cache budget of the 1TB, which makes a much bigger difference here than the headline speed suggests if you''re moving 200GB+ game installs.', NULL, '["Gen 2x2 2000 MB/s","2TB capacity","Budget pricing","Aluminum body"]', '["3-year warranty","No IP rating","Caps at 1050 on Gen 2 hosts","Sustained writes still dip on long transfers"]', 8.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 2, 23, 'OWC Envoy Pro FX 1TB', 'owc-envoy-pro-fx-1tb', 'OWCTB3ENV1', 'B08L3R3KTJ', 'OWC Envoy Pro FX', 1000, 'External', 'Thunderbolt 3', 2800, 2800, 600, 3, 'A 2800 MB/s Thunderbolt 3 portable in an aluminum unibody the size of an iPhone. The Envoy Pro FX is one of the cleanest Thunderbolt 3 portable SSDs in the price tier — nothing fancy, just speed and thermal management in a small case.', NULL, '["Thunderbolt 3 2800/2800 MB/s","Aluminum unibody heatsink","3-year warranty","Premium build quality"]', '["USB-C/Thunderbolt cable included is short","Requires Thunderbolt 3/4 host (USB caps at 1050)","3-year warranty (not 5)","Premium pricing"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 2, 23, 'OWC Envoy Pro FX 2TB', 'owc-envoy-pro-fx-2tb', 'OWCTB3ENV2', 'B08L3R3W4C', 'OWC Envoy Pro FX', 2000, 'External', 'Thunderbolt 3', 2800, 2800, 1200, 3, 'The 2TB Envoy Pro FX keeps the same small unibody of the 1TB but scales the die stack. The sustained write behavior on the 2TB stays pegged at 2800 MB/s well past 500GB on a Thunderbolt 3 host.', NULL, '["Thunderbolt 3 2800/2800 MB/s","Sustained writes hold past 500GB on 2TB","Aluminum unibody","3-year warranty"]', '["Premium pricing","3-year warranty","Cable is short","Requires Thunderbolt 3/4 host"]', 8.8, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 2, 23, 'OWC Envoy Pro FX 4TB', 'owc-envoy-pro-fx-4tb', 'OWCTB3ENV4', 'B0B3S4PNQB', 'OWC Envoy Pro FX', 4000, 'External', 'Thunderbolt 3', 2800, 2800, 2400, 3, '4TB of Thunderbolt 3 storage in an aluminum unibody barely larger than the 1TB. The Envoy Pro FX 4TB is a niche-of-one — buyers typically pay the premium for video editing workflows where 4000 MB/s sustained links plus 4TB of room actually matter.', NULL, '["Thunderbolt 3 + 4TB","Aluminum unibody","2800 sustained writes","3-year warranty"]', '["Premium pricing","3-year warranty","Requires Thunderbolt 3/4 host","Cable included is short"]', 8.9, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 24, 'Lexar SL100 Pro 1TB', 'lexar-sl100-pro-1tb', 'LXES100-1TRNN', 'B07WGVN5XN', 'Lexar SL100 Pro', 1000, 'External', 'USB 3.2 Gen 2', 950, 950, 600, 3, 'A 950 MB/s Gen 2 portable in a brushed-aluminum case the size of a credit card. The SL100 Pro is one of the smallest 1TB Gen 2 SSDs at retail — buy it for the form factor, not the rated speed (which undershoots the Gen 2 ceiling).', NULL, '["Brushed-aluminum case","950 MB/s read","Tiny credit-card footprint","USB-C cable included"]', '["950 MB/s — slower than full Gen 2","3-year warranty","No IP rating","Premium pricing vs ADATA SE800"]', 7.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 24, 'Lexar SL100 Pro 2TB', 'lexar-sl100-pro-2tb', 'LXES100-2TRNN', 'B07WGVTHZ2', 'Lexar SL100 Pro', 2000, 'External', 'USB 3.2 Gen 2', 950, 950, 1200, 3, 'The 2TB SL100 Pro keeps the same brushed-aluminum credit-card footprint of the 1TB — famously pocketable but only marginally faster on sustained writes thanks to the larger SLC cache.', NULL, '["2TB in credit-card footprint","950 MB/s read","Aluminum body","USB-C cable"]', '["950 MB/s (not full Gen 2)","3-year warranty","No IP rating","Sustained writes dip after cache"]', 7.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 24, 'Lexar SL660 1TB', 'lexar-sl660-1tb', 'LXBL600-1TRNN', 'B09L4TGJZQ', 'Lexar SL660', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 600, 3, 'A premium 2000 MB/s Gen 2x2 portable with an aluminum body and an RGB-lit Logo. The RGB is a divisive feature but the performance is real, and the build quality distinguishes it from cheaper Gen 2x2 peers like the Patriot Evlvr.', NULL, '["Gen 2x2 2000/2000 MB/s","Aluminum body","3-year warranty","USB-C cable included"]', '["RGB is polarizing","3-year warranty","No IP rating","Caps at 1050 on Gen 2 hosts"]', 8.1, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 24, 'Lexar SL660 2TB', 'lexar-sl660-2tb', 'LXBL600-2TRNN', 'B09L4TJD8C', 'Lexar SL660', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 3, 'The 2TB SL660 doubles SLC cache budget over the 1TB. RGB and aluminum body preserved — a competitive Gen 2x2 2TB at moderate pricing. Worth comparing with the Kingston XS2000 2TB and Patriot Evlvr 2TB.', NULL, '["Gen 2x2 2000 MB/s","2TB storage","Aluminum body","3-year warranty"]', '["RGB","No IP rating","Caps at 1050 MB/s on Gen 2 hosts","3-year warranty only"]', 8.2, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 25, 'Netac ZX1 1TB', 'netac-zx1-1tb', 'ZX1-1T', 'B0B2RYXKN2', 'Netac ZX1', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 1800, 600, 3, 'A budget Gen 2x2 portable from Netac — aggressive price vs the brand-name tier. The 1800 MB/s write rating is real but drops further on sustained workloads past the SLC cache. A valid budget pick for game-library overflow where peak sustained write doesn''t matter.', NULL, '["Gen 2x2 2000 read","Budget pricing","Compact form factor","USB-C cable included"]', '["1800 MB/s write (not 2000)","3-year warranty","Plastic body","No IP rating"]', 7.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 25, 'Netac ZX1 2TB', 'netac-zx1-2tb', 'ZX1-2T', 'B0B2RZFRW3', 'Netac ZX1', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 1800, 1200, 3, 'The 2TB ZX1 doubles both capacity and SLC cache budget. Budget pricing holds — among the most affordable 2TB Gen 2x2 portables at retail. Buyers should temper expectations on sustained writes after the SLC cache exhausts.', NULL, '["Gen 2x2 2000/1800 MB/s","Budget pricing","2400 TBW","Compact form factor"]', '["3-year warranty","Plastic body","No IP rating","Sustained writes dip sharply after cache fills"]', 7.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 26, 'Silicon Power PC60 1TB', 'silicon-power-pc60-1tb', 'SP1TBPC60K', 'B08YYB7HWV', 'Silicon Power PC60', 1000, 'External', 'USB 3.2 Gen 2', 1000, 900, 600, 3, 'A budget 1050-class Gen 2 portable from Silicon Power — one of the cheapest brand-name 1TB Gen 2 SSDs at retail. Plastic body, gray aesthetic, no IP rating. Real value is cost-per-TB, not build or sustained performance.', NULL, '["1000 MB/s read","Budget pricing","Compact form factor","USB-C cable included"]', '["Plastic body","3-year warranty","No IP rating","900 MB/s write"]', 7.3, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 26, 'Silicon Power PC60 2TB', 'silicon-power-pc60-2tb', 'SP2TBPC60K', 'B09P3SF1FB', 'Silicon Power PC60', 2000, 'External', 'USB 3.2 Gen 2', 1000, 900, 1200, 3, 'A 2TB budget Gen 2 portable aimed at game-library cold storage for PS5/Xbox. Aggressive pricing makes it competitive against the Seagate One Touch 2TB on sale. Not a drive for sustained-write-heavy creative workflows.', NULL, '["2TB budget Gen 2","1000 MB/s read","Compact profile","USB-C cable included"]', '["900 MB/s write","Plastic body","No IP rating","3-year warranty"]', 7.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 27, 'Transcend ESD310C 1TB', 'transcend-esd310c-1tb', 'TS1TESD310C', 'B0BLNQYTNS', 'Transcend ESD310C', 1000, 'External', 'USB 3.2 Gen 2', 1050, 950, 600, 3, 'A tiny 1050-class Gen 2 portable from a long-established memory brand. ESD310C is one of the smallest 1TB Gen 2 SSDs at retail — small enough to be lost in a bag. Buy it for the form factor over sustained performance.', NULL, '["1050/950 MB/s","Tiny credit-card footprint","3-year warranty","Rotating cap protects USB-C port"]', '["Plastic body","No IP rating","3-year warranty","Sustained writes dip after cache"]', 7.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 27, 'Transcend ESD310C 2TB', 'transcend-esd310c-2tb', 'TS2TESD310C', 'B0C6KB3ZSM', 'Transcend ESD310C', 2000, 'External', 'USB 3.2 Gen 2', 1050, 950, 1200, 3, 'The 2TB ESD310C keeps the same tiny plastic credit-card footprint of the 1TB — Transcend fits an unusually large stack in an unusually small case. The 2TB cache budget also holds the 950 MB/s write past 200GB on long transfers.', NULL, '["1050/950 MB/s","Tiny footprint","2400 TBW endurance","Rotating cap protects USB-C port"]', '["Plastic body","No IP rating","3-year warranty","Premium vs ADATA SE800 2TB"]', 7.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 28, 'Inland Performance 1TB', 'inland-performance-1tb', 'INP-1TB', 'B0B7CHQ6H5', 'Inland Performance', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 600, 3, 'A MicroCenter house-brand Gen 2x2 portable at aggressive pricing. The Performance line is built on standard NAND — not exceptional build but cheap for the speed tier, and easy to find in MicroCenter retail stores.', NULL, '["Gen 2x2 2000 MB/s","MicroCenter-retail pricing","3-year warranty","USB-C cable included"]', '["Plastic body","3-year warranty","No IP rating","Caps at 1050 on Gen 2 hosts"]', 7.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 28, 'Inland Performance 2TB', 'inland-performance-2tb', 'INP-2TB', 'B0B7CHRJZV', 'Inland Performance', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 3, 'A 2TB Gen 2x2 portable from Inland''s house line. Aggressive pricing vs the brand-name tier — while MicroCenter regularly stocks them in stores, online stock availability is inconsistent.', NULL, '["Gen 2x2 2000 MB/s","2TB capacity","MicroCenter retail availability","3-year warranty"]', '["Plastic body","No IP rating","Inconsistent online availability","Sustained writes dip after cache"]', 7.8, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 29, 'ORICO UFSD 1TB', 'orico-ufsd-1tb', 'ORICO-UFSD-1T', 'B0CY7P4KQW', 'ORICO UFSD', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 600, 3, 'A newer Amazon-direct Gen 2x2 portable from ORICO. Aggressive sale pricing, aluminum body, full 2000 MB/s rating — but ratings from independent reviews are mixed on sustained writes after SLC cache exhaustion.', NULL, '["Gen 2x2 2000 MB/s","Aggressive Amazon sale pricing","Aluminum body","USB-C cable included"]', '["3-year warranty","No IP rating","Mixed sustained write reviews","Newer market entrant"]', 7.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 29, 'ORICO UFSD 2TB', 'orico-ufsd-2tb', 'ORICO-UFSD-2T', 'B0CY7P4PZ6', 'ORICO UFSD', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 3, 'The 2TB UFSD doubles capacity of the ORICO Gen 2x2 line. Pricing typically tracks the Inland Performance 2TB — both are house-tier aggressive pills. The aluminum body distinguishes the ORICO visually from the plastic-bodied Inland.', NULL, '["Gen 2x2 2000 MB/s","2TB capacity","Aluminum body","Aggressive pricing"]', '["3-year warranty","No IP rating","Mixed sustained write reviews","Newer brand with thin retail track record"]', 7.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 1, 30, 'SSK SHE030 1TB', 'ssk-she030-1tb', 'SHE030-1T', 'B0CF7Q8HND', 'SSK SHE030', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 3, 'A budget 1050-class Gen 2 portable from SSK. Compatible with PS5 expandable storage (USB cold library) and Xbox cold storage. Aggressive pricing makes it a value-tier option for console-game overflow where peak sustained speed is not critical.', NULL, '["1050 MB/s read","Budget aggressive price","PS5/Xbox cold-library compatible","USB-C cable included"]', '["1000 MB/s write (not full 1050)","3-year warranty","No IP rating","Sustained writes dip after cache"]', 7.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('externalssds', 2, 30, 'SSK PM510 USB4 1TB', 'ssk-pm510-usb4-1tb', 'PM510-1T', 'B0C7R43F1M', 'SSK PM510 USB4', 1000, 'External', 'USB4', 3200, 2800, 600, 3, 'AUSB4 portable at enthusiast-grade specs — 3200 MB/s read over USB4 / Thunderbolt 4 hosts. The PM510 is one of the more affordable USB4 portables, an entry point for video editors who need Thunderbolt-class speeds but don''t want to pay LaCie or OWC premium.', NULL, '["USB4 3200 MB/s","Thunderbolt 4 compatible","Aluminum body","3-year warranty"]', '["3-year warranty (not 5)","Requires USB4/Thunderbolt 4 host","Premium vs Gen 2 drives on USB-C host","Sustained writes dip after cache"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 1, 'Samsung T7 Portable 500GB', 'samsung-t7-portable-500gb', 'MU-PC500S', 'B0874WWDJY', 'Samsung T7', 500, 'External', 'USB 3.2 Gen 2', 1050, 1000, 300, 3, 'The 500GB T7 is the minimalist baseline — a half-terabyte of well-supported portable storage at the smallest physical size Samsung ships in this line. The right pick if your portable SSD use case is launching apps and carting around working documents rather than media libraries.', NULL, '["Tiny aluminum body","AES 256-bit hardware encryption","Samsung''s broad device compatibility","Both USB-C cable included"]', '["No IP rating","300 TBW at this size","Plastic-feeling top","No USB-A cable in box"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 1, 'Samsung T7 Portable 2TB', 'samsung-t7-portable-2tb', 'MU-PC2T0S', 'B0874WWDJY', 'Samsung T7', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'The 2TB T7 is the size most portable-SSD buyers actually want — enough room for a laptop worth of working files plus media library, in a metal case that fits in a passport pocket. The 2TB stack also sustains writes past 300GB without the dip the 1TB T7 hits.', NULL, '["2TB Gen 2","Sustained writes hold past 300GB","AES 256-bit hardware encryption","Cheapest $/TB in the T7 line"]', '["No IP rating","380 TBW at the 2TB tier","Plastic top plate","C-to-C cable only"]', 9.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 1, 'Samsung T7 Portable 4TB', 'samsung-t7-portable-4tb', 'MU-PC4T0S', 'B08S2BYTM7', 'Samsung T7', 4000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 2400, 3, 'The 4TB T7 is the convenience-grade size for travelers who carry whole media libraries — full photo shoots, complete plex libraries, plus Time Machine backup. 2400 TBW on the 4TB tier is meaningful endurance for a portable.', NULL, '["4TB portable Gen 2","2400 TBW endurance","Sustained writes pegged","Hardware encryption"]', '["No IP rating","C-to-C cable only","Premium pricing over T7 2TB","Plastic top plate scratches easily"]', 9.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 1, 'Samsung T7 Touch Portable 1TB', 'samsung-t7-touch-portable-1tb', 'MU-PC1T0K', 'B089GVKY7J', 'Samsung T7 Touch', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 3, 'A fingerprint-secured variant of the portable T7 — three fingerprints supported, three registered per drive. Useful for carriers of client-confidential data (lawyers and consultants) where the cost of a lost drive without encryption is the limiting factor, not the cost of the drive.', NULL, '["Fingerprint unlock — no password typing","AES 256-bit hardware encryption","Same 1050/1000 MB/s speeds as base T7","Cool-running aluminum chassis"]', '["Fingerprint enrollment is desktop-only","No IP rating","Premium over standard T7","C-to-C cable only"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 1, 'Samsung T7 Touch Portable 2TB', 'samsung-t7-touch-portable-2tb', 'MU-PC2T0K', 'B089GVND1Z', 'Samsung T7 Touch', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'The 2TB T7 Touch adds the fingerprint unlock of the 1TB version to a 2TB stack. The sustained writes stay pegged at 1000 MB/s past 300GB on this die stack — same as the standard 2TB T7.', NULL, '["Fingerprint unlock","2TB storage","Sustained 1000 MB/s writes","Same AES 256-bit hardware encryption"]', '["Fingerprint enrollment desktop-only","Premium over base T7","No IP rating","C-to-C cable only"]', 8.8, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 6, 1, 'Samsung T7 Shield Portable 2TB', 'samsung-t7-shield-portable-2tb', 'MU-PE2T0S', 'B09V7KM2VC', 'Samsung T7 Shield', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'A 2TB ruggedized T7 Shield — the middle of the T7 Shield line and arguably the most-purchased capacity in the family. A standard travel-shoot companion for outdoor photographers and extreme-sports shooters who need both real capacity and proper ruggedization.', NULL, '["IP65 rugged body","2TB capacity","3-meter drop rated","Samsung''s broad device compatibility"]', '["1050/1000 MB/s (Gen 2 ceiling)","3-year warranty","Rubber exterior collects pocket lint","C-to-C cable only"]', 9.3, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 1, 'Samsung T9 Portable 2TB', 'samsung-t9-portable-2tb', 'MU-PD2T0S', 'B0CHFSMWHK', 'Samsung T9', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 5, 'The 2TB T9 portable doubles the write endurance of the 1TB T9. The T9''s premium for the Gen 2x2 link matters on portable workflow where you''re moving enormous files regularly — PS5 game imports, large B-roll offloads — and don''t want to wait Gen 2 speeds.', NULL, '["Gen 2x2 2000/2000 MB/s","5-year warranty","Sustained writes hold past 300GB","USB-C cable included"]', '["Premium pricing vs T7 2TB","Requires Gen 2x2 host above 1050 MB/s","Heavier than the T7","No hardware AES encryption"]', 9.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 1, 'Samsung T9 Portable 4TB', 'samsung-t9-portable-4tb', 'MU-PD4T0S', 'B0CHFSZX9W', 'Samsung T9', 4000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 2400, 5, 'The 4TB T9 portable is genuinely rare — most 4TB external SSDs cap at Gen 2 (10Gbps) speeds. The T9 4TB holds 2000 MB/s sustained reads AND writes at 4TB. The right drive for working video pros who genuinely travel with 4TB of working RAW footage and need Gen 2x2 link speeds.', NULL, '["Gen 2x2 + 4TB","2400 TBW endurance","5-year warranty","Sustained writes hold past 500GB"]', '["Premium pricing","Requires Gen 2x2 host above 1050 MB/s","Heavier than the 4TB T7","No hardware AES encryption"]', 9.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 6, 4, 'SanDisk Extreme Pro Portable 2TB', 'sandisk-extreme-pro-portable-2tb', 'SDSSDE61-2T00', 'B08GV9QM8R', 'SanDisk Extreme Pro', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 5, 'A 2TB IP55 rugged portable SSD with a 5-year warranty — the SanDisk sweet-spot for outdoor photographers traveling with RAW libraries. The 5-year coverage beats Samsung''s T7 family by 2 years, and the IP55 rating beats it by IP rating points.', NULL, '["IP55 rugged body","5-year warranty","Both USB-C and USB-A cables included","Sustained writes hold past 200GB on 2TB"]', '["Rubber bumper collects pocket lint","Sustained writes can dip on hot days","No hardware encryption","Premium vs non-rugged T7 2TB"]', 9.2, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 6, 4, 'SanDisk Extreme Pro Portable 4TB', 'sandisk-extreme-pro-portable-4tb', 'SDSSDE61-4T00', 'B08RX3343D', 'SanDisk Extreme Pro', 4000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 2400, 5, 'The 4TB Extreme Pro is the largest portable SSD in SanDisk''s ruggedized line and a direct competitor to the Samsung T7 Shield 4TB. The 5-year warranty plus IP55 rubber armor are distinguishing factors vs other 4TB portable SSDs — most peers only offer 3.', NULL, '["4TB @ IP55 rugged","5-year warranty","Both cables in box","2400 TBW endurance"]', '["Rubber exterior collects lint","Premium pricing vs 4TB T7","Sustained writes can dip on thermal load","Heavier than non-rugged 4TB portables"]', 9.3, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 6, 4, 'SanDisk Extreme Portable 2TB', 'sandisk-extreme-portable-2tb', 'SDSSDE61-2T00-G25', 'B08PG2M6VK', 'SanDisk Extreme', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'A 2TB IP55 rugged portable — the budget sibling of the Extreme Pro 2TB. Same IP55 body and 1050 MB/s read, just dropped to a 3-year warranty and slower sustained writes on long transfers. Worth it if your use case is backup and console library overflow rather than video editing.', NULL, '["IP55 rugged body","2TB capacity","Both cables in box","Budget pricing vs Extreme Pro 2TB"]', '["3-year warranty (vs Pro''s 5)","Slower sustained writes after cache","Slower write on long transfers","No encryption"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 2, 'Crucial X9 Pro Portable 2TB', 'crucial-x9-pro-portable-2tb', 'CT2000X9PROSSD9', 'B0C9WKQFY7', 'Crucial X9 Pro', 2000, 'External', 'USB 3.2 Gen 2', 1050, 950, 1200, 5, 'The 2TB X9 Pro doubles the cache budget over the 1TB. Real TLC NAND and 5-year warranty gives Crucial''s premium portable line a longer-lived write endurance than consumer QLC alternatives. The right buy for editors who want a working drive rather than a backup drive.', NULL, '["Real TLC NAND","5-year warranty","1200 TBW endurance","Cool-running aluminum body"]', '["No IP rating","950 MB/s sustained writes","C-to-C cable only","No back-compatible USB-A cable"]', 9.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 2, 'Crucial X10 Pro Portable 2TB', 'crucial-x10-pro-portable-2tb', 'CT2000X10PROSSD9', 'B0C9WJL63B', 'Crucial X10 Pro', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 5, 'The 2TB X10 Pro is the drive Crucial built for video pros on Gen 2x2 hosts — full 2000 MB/s sustained, real TLC NAND, 5-year warranty, AES 256-bit hardware encryption. A Canon-level competitor to the Samsung T9 2TB at the same $/TB.', NULL, '["Gen 2x2 2000 MB/s","5-year warranty","Real TLC NAND with AES","1200 TBW"]', '["Only useful on Gen 2x2 hosts","No IP rating","C-to-C cable only","Premium pricing on non-2x2 hosts"]', 9.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 2, 'Crucial X10 Pro Portable 4TB', 'crucial-x10-pro-portable-4tb', 'CT4000X10PROSSD9', 'B0C9WJQ9GP', 'Crucial X10 Pro', 4000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 2400, 5, 'A 4TB Gen 2x2 portable with the full Crucial X10 Pro spec — TLC NAND, AES, 5-year warranty, 2400 TBW. Among the few 4TB Gen 2x2 SSDs at retail, the closest competitor is the Sabrent Rocket Nano V2 4TB.', NULL, '["Gen 2x2 + 4TB","Real TLC NAND","5-year warranty + 2400 TBW","Hardware encryption"]', '["Only useful on Gen 2x2 hosts","No IP rating","Premium pricing","C-to-C cable only"]', 9.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 2, 'Crucial X6 Portable 1TB', 'crucial-x6-portable-1tb', 'CT1000X6SSD9', 'B0CL5ZB4WR', 'Crucial X6', 1000, 'External', 'USB 3.2 Gen 2', 800, 800, 600, 3, 'A budget 1TB Gen 2 portable for the portable-SSD crowd — 800 MB/s is below the Gen 2 ceiling but exactly what''s needed for Time Machine and laptop backup workflows that don''t depend on peak speeds. Picks IP-rating-free build to keep price aggressive.', NULL, '["800 MB/s read","Budget pricing","PS5/Xbox cold-library compatible","Tiny plastic footprint"]', '["800 MB/s — half the Gen 2 ceiling","3-year warranty","No IP rating","Plastic body"]', 7.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 2, 'Crucial X6 Portable 2TB', 'crucial-x6-portable-2tb', 'CT2000X6SSD9', 'B0CL5ZB68L', 'Crucial X6', 2000, 'External', 'USB 3.2 Gen 2', 800, 800, 1200, 3, 'A 2TB budget portable SSD from Crucial — the X6 line consistently comes in cheaper per-TB than the T7 family. The 2TB keeps the 800 MB/s cap but the larger SLC cache holds the rate longer before slowing.', NULL, '["2TB budget Gen 2","800 MB/s read","PS5/Xbox cold-library compatible","Cool under load"]', '["800 MB/s — half Gen 2 ceiling","3-year warranty","No IP rating","Plastic body"]', 7.8, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 2, 'Crucial X6 Portable 4TB', 'crucial-x6-portable-4tb', 'CT4000X6SSD9', 'B0CL5ZBGD7', 'Crucial X6', 4000, 'External', 'USB 3.2 Gen 2', 800, 800, 2400, 3, 'A 4TB portable at the X6''s budget price is closer to spinning-rust economics than SSD. The 800 MB/s ceiling doesn''t matter for the use case — the entire point is capacious portable cold library overflow for PS5, Xbox, or photo archive, not peak throughput.', NULL, '["4TB at budget pricing","PS5/Xbox cold-library friendly","Cool operation","3-year warranty"]', '["800 MB/s cap","Plastic body","No IP rating","3-year warranty"]', 8.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 2, 'Crucial X8 Portable 1TB', 'crucial-x8-portable-1tb', 'CT1000X8SSD9', 'B098FH7K96', 'Crucial X8', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 3, 'The X8 is the previous-gen Crucial premium portable — superseded by the X9 Pro but often available at discounts. Same 1050/1000 MB/s, aluminum unibody, but a 3-year warranty. Worth buying if the sale price beats the X9 Pro by a meaningful margin.', NULL, '["1050/1000 MB/s","Anodized aluminum body","Often on clearance","3-year warranty"]', '["Superseded by X9 Pro","No hardware encryption","3-year (not 5) warranty","No IP rating"]', 8.3, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 2, 'Crucial X8 Portable 2TB', 'crucial-x8-portable-2tb', 'CT2000X8SSD9', 'B098FH7KDR', 'Crucial X8', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'A 2TB solid-aluminum previous-gen Crucial X8 portable — often discounted during clearance cycles. Buy when the savings over the X9 Pro 2TB are real (30%+); ignore when pricing is competitive with the X9 Pro (which has the 5-year warranty).', NULL, '["1050/1000 MB/s","Aluminum unibody","Often discounted","1200 TBW endurance"]', '["Superseded by X9 Pro","3-year warranty only","No hardware encryption","No IP rating"]', 8.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 3, 'WD My Passport SSD Portable 1TB', 'wd-my-passport-ssd-portable-1tb', 'WDBKVX0010BBK', 'B08F27QGHX', 'WD My Passport SSD', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 3, 'A 1TB WD My Passport SSD with a slim profile and 256-bit AES hardware encryption. The slim metal-and-plastic body is half the thickness of WD''s non-SSD My Passport HDD — both USB-C and USB-A cables are included, removing the classic "Mac needs a converter" hassle.', NULL, '["1050/1000 MB/s","Slim profile","256-bit AES hardware encryption","Both USB-C and USB-A cables included"]', '["3-year warranty only","Sustained writes dip after SLC cache","Plastic-feel ridge pattern","No IP rating"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 3, 'WD My Passport SSD Portable 2TB', 'wd-my-passport-ssd-portable-2tb', 'WDBKVX0260BBK', 'B08F27QGHX', 'WD My Passport SSD', 2000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 1200, 3, 'A 2TB WD My Passport SSD in the same slim form factor. Both USB-C and USB-A cables in box, hardware encryption in WD Dashboard software. A value pick vs the T7 2TB when on sale — with the caveat that the 3-year warranty is shorter than Samsung''s.', NULL, '["2TB slim Gen 2","256-bit AES hardware encryption","Both cables included","Often on sale below T7 pricing"]', '["3-year warranty","Sustained writes dip on large transfers","Plastic top half","WD Dashboard software required for encryption"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 3, 'WD My Passport SSD Portable 4TB', 'wd-my-passport-ssd-portable-4tb', 'WDBKVX0460BBK', 'B0B3Q5GT7S', 'WD My Passport SSD', 4000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 2400, 3, 'A 4TB My Passport SSD portable — same physical package as the 1TB/2TB but with the 4TB die stack. The biggest single-portable WD ships and one of the few 4TB portable SSDs at retail, period. Compares closely with the Samsung T7 4TB.', NULL, '["4TB slim form factor","2400 TBW endurance","AES hardware encryption","Both cables in box"]', '["3-year warranty","Premium pricing vs T7 4TB on sale","Sustained writes dip on extreme loads","Plastic-feel top plate"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 3, 'WD Black P50 Game Drive SSD Portable 1TB', 'wd-black-p50-portable-1tb', 'WDBNAJ0010BBK', 'B07XNT5L7Q', 'WD Black P50', 1000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 600, 5, 'A Gen 2x2 portable aimed squarely at PS5/Xbox cold-library expansion. The Black P50 has a 5-year warranty — best in its tier. RGB-free compared to the Seagate FireCuda — preferred by buyers who don''t want gaming-aesthetic drives.', NULL, '["Gen 2x2 2000 MB/s","5-year warranty","Console compatible","Both cables in box"]', '["Caps at 1050 on Gen 2 hosts","Gen 2x2 price premium","Aesthetic (some find it dull)","Larger footprint than T7 1TB"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 3, 'WD Black P50 Game Drive SSD Portable 2TB', 'wd-black-p50-portable-2tb', 'WDBNAJ0020BBK', 'B07XNT5L7V', 'WD Black P50', 2000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 1200, 5, 'The 2TB Black P50 doubles the SLC cache budget of the 1TB — sustained writes hold 2000 MB/s noticeably longer than on the 1TB. RGB-free Gen 2x2 with a 5-year warranty is genuinely rare; the chief competitor is the Kingston XS2000 2TB, also 5-year but lower price.', NULL, '["Gen 2x2 + 2TB","5-year warranty","RGB-free gamer aesthetic","Both cables in box"]', '["Caps at 1050 on Gen 2 hosts","Premium pricing vs Kingston XS2000","Larger than typical 2TB portable","Footprint heavier than T7"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 3, 'WD Black P50 Game Drive SSD Portable 4TB', 'wd-black-p50-portable-4tb', 'WDBNAJ0040BBK', 'B0B5HH6TC9', 'WD Black P50', 4000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 2400, 5, 'A 4TB Black P50 with 5-year warranty — RGB-free PS5/Xbox cold-library overflow. The largest Gen 2x2 SSD with a console-gamer retail pricing model. Difficult to compete with at this capacity × warranty intersection.', NULL, '["Gen 2x2 + 4TB + 5-year warranty","RGB-free gamer aesthetic","Console cold-library ready","Both cables in box"]', '["Caps at 1050 on Gen 2 hosts","Premium price vs Gen 2 4TB peers","Larger footprint","Premium over T9 4TB on normal hosts"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 5, 'Seagate One Touch SSD Portable 500GB', 'seagate-one-touch-portable-500gb', 'STKS5000400', 'B08FS5L3HN', 'Seagate One Touch', 500, 'External', 'USB 3.2 Gen 2', 1030, 1030, 300, 3, 'A 500GB One Touch is Seagate''s bottom-of-line portable SSD — usually the cheapest brand-name Gen 2 1TB-and-below portable at retail. The bundle includes Rescue data recovery (extending Seagate''s warranty protection into physical damage recovery).', NULL, '["1030 MB/s read","Budget pricing","Both USB-C and USB-A cables","Rescue data recovery plan"]', '["Sustained writes dip after 50GB cache","3-year warranty","No IP rating","Plastic body"]', 7.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 5, 'Seagate One Touch SSD Portable 1TB', 'seagate-one-touch-portable-1tb', 'STKS1000400', 'B08FS5NBQM', 'Seagate One Touch', 1000, 'External', 'USB 3.2 Gen 2', 1030, 1030, 600, 3, 'A 1TB budget portable from Seagate — typically the lowest-priced 1TB brand-name Gen 2 portable SSD available. Comes with the Resident Rescue data-recovery plan, which is meaningful coverage at a price point where the drive is seen as disposable.', NULL, '["1030 MB/s budget drive","Both USB-C/A cables","Rescue data recovery plan","Often cheapest brand-name 1TB Gen 2"]', '["Sustained writes dip sharply after cache","3-year warranty","Plastic body","No encryption on Windows"]', 7.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 5, 'Seagate One Touch SSD Portable 2TB', 'seagate-one-touch-portable-2tb', 'STKS2000400', 'B08FS5PYCQ', 'Seagate One Touch', 2000, 'External', 'USB 3.2 Gen 2', 1030, 1030, 1200, 3, 'The 2TB One Touch is the realistic minimum for game-library cold storage and Time Machine backups at typical Seagate sale pricing. The larger die stack holds the rated 1030 MB/s write distinctly longer than the 1TB variant before SLC cache exhausts.', NULL, '["1030 MB/s rated","Both cables","Rescue data recovery plan","Larger SLC cache than 1TB"]', '["Sustained writes still drop after cache","3-year warranty","Plastic body","No IP rating"]', 7.8, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 5, 'Seagate FireCuda Gaming SSD Portable 1TB', 'seagate-firecuda-portable-1tb', 'STFS1000400', 'B0936BQ1FY', 'Seagate FireCuda', 1000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 600, 5, 'A Gen 2x2 portable for PS5 cold-library expansion with an RGB center strip that lights up when in use. The 5-year warranty is the genuine selling point — a US-bound console-game cold-library build at price parity with non-RGB Gen 2x2 alternatives prefers the 5-year warranty.', NULL, '["Gen 2x2 2000 MB/s","5-year RGB RGB gaming SSD","Both cables included","Console-game cold-library"]', '["Caps at 1050 on Gen 2 hosts","RGB lighting is a layer-of-issue decision","Premium pricing","Larger footprint than T7"]', 8.3, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 5, 'Seagate FireCuda Gaming SSD Portable 2TB', 'seagate-firecuda-portable-2tb', 'STFS2000400', 'B0936BPJTV', 'Seagate FireCuda', 2000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 1200, 5, 'A 2TB FireCuda Gaming SSD with the full 5-year warranty and an RGB-lit center strip. Gen 2x2 over USB-C, headphone-aesthetic RGB, and a 5-year warranty give the FireCuda a defensible niche against the WD Black P50 2TB.', NULL, '["Gen 2x2 + 2TB","5-year warranty","Both cables in box","Console cold-library ready"]', '["RGB","Caps at 1050 on Gen 2 hosts","Premium pricing","Larger footprint than T7"]', 8.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 5, 'Seagate FireCuda Gaming SSD Portable 4TB', 'seagate-firecuda-portable-4tb', 'STFS4000400', 'B09V1GZ6ZV', 'Seagate FireCuda', 4000, 'External', 'USB 3.2 Gen 2', 2000, 2000, 2400, 5, 'A 4TB Gen 2x2 RGB-lit gaming SSD — the largest single-portable FireCuda with the full 5-year Seagate warranty. Real value-add at this size: 5 years + Rescue data recovery plan bundled in. PS5/Xbox cold-library-ready, easily handling moving multi-game installs at 2000 MB/s.', NULL, '["4TB Gen 2x2 + 5-year warranty","RGB gaming aesthetic","Both cables in box","Console cold-library ready"]', '["RGB","Caps at 1050 on Gen 2 hosts","Premium pricing","Larger than typical 4TB portable SSD"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 9, 'Corsair EX100U Portable 2TB', 'corsair-ex100u-portable-2tb', 'CSSD-EX100U-2TB', 'B0BGJ1JFKG', 'Corsair EX100U', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 1800, 1200, 3, 'A 2TB Gen 2x2 portable with the Corsair aluminum body. Write speed drops to 1800 MB/s over the 1TB 2000 - a 10% bump down for the larger die stack. Still above 2GB/s on paper for long transfers as long as the host is Gen 2x2.', NULL, '["Gen 2x2 + 2TB","Cool aluminum body","Both cables in box","1800 MB/s sustained write"]', '["3-year warranty","1800 (not 2000) MB/s write on 2TB","Premium pricing","No IP rating"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 9, 'Corsair EX400U Portable 1TB', 'corsair-ex400u-portable-1tb', 'CSSD-EX400U-1TB', 'B0DR379KSW', 'Corsair EX400U', 1000, 'External', 'USB4', 3300, 3000, 600, 5, 'A USB4 portable from Corsair with 3300 MB/s read on Thunderbolt 4 / USB4 hosts - and the full 5-year warranty. The EX400U 1TB portable is a competitive USB4 entry point for video editors who need Thunderbolt-class speeds without the LaCie price tag.', NULL, '["USB4 3300 MB/s read","5-year warranty","Full 40Gbps USB4 link","Console compatible"]', '["Only useful on USB4/Thunderbolt 4 host","Premium pricing","Cable is short","No IP rating"]', 9.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 6, 21, 'LaCie Rugged SSD Pro Portable 1TB', 'lacie-rugged-ssd-pro-portable-1tb', 'SPR900', 'B08FN34GWY', 'LaCie Rugged SSD Pro', 1000, 'External', 'Thunderbolt 3', 2700, 1900, 600, 5, 'The portable-shooters drive - Thunderbolt 3 in LaCie iconic orange-rubber bumpers and 5-year Rescue included. Standard-issue for outdoor wedding, extreme-sports, news, and travel videographers who genuinely need both real-time 6K editing AND a drive that survives the field.', NULL, '["Thunderbolt 3 2700 MB/s","IP67 + 3-meter drop + 1-ton crush","5-year Rescue included","Integrated Thunderbolt cable"]', '["Premium pricing","Bulky","Cable integrated - replacement requires LaCie service","Heavier than non-rugged peers"]', 9.0, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 6, 21, 'LaCie Rugged SSD Pro Portable 2TB', 'lacie-rugged-ssd-pro-portable-2tb', 'SPR910', 'B08FN8WVG2', 'LaCie Rugged SSD Pro', 2000, 'External', 'Thunderbolt 3', 2700, 1900, 1200, 5, 'The 2TB Rugged SSD Pro is the field-shoot workhorse - Thunderbolt 3 stays pegged at 2700 MB/s sustained on the 2TB die stack past 500GB. The standard drive in outdoor wedding videographers kits, news shooters, and documentary teams in difficult environments.', NULL, '["Thunderbolt 3 2700 MB/s + 2TB","IP67 rugged body","5-year Rescue","Sustained writes stay pegged on 2TB stack"]', '["Premium pricing","Bulky orange bumper","Cable integrated","Heavier than non-rugged 2TB peers"]', 9.1, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 6, 21, 'LaCie Rugged SSD Pro Portable 4TB', 'lacie-rugged-ssd-pro-portable-4tb', 'SPR920', 'B0B5DLLVMC', 'LaCie Rugged SSD Pro', 4000, 'External', 'Thunderbolt 3', 2700, 1900, 2400, 5, 'A 4TB Thunderbolt 3 portable in the iconic LaCie rugged orange body - one-of-one at this capacity/speed tier. Largely without competitor at 4TB Thunderbolt 3 + IP67 = niche product, premium pricing pairs the niche.', NULL, '["Thunderbolt 3 + 4TB + IP67","5-year Rescue","3-meter drop + 1-ton crush","2400 TBW endurance"]', '["Premium pricing","Bulky","Cable integrated","Only worth it for actual Thunderbolt workflows"]', 9.2, 0, 1, NULL, NULL);
