('portablessds', 6, 21, 'LaCie Rugged SSD Portable 1TB', 'lacie-rugged-ssd-portable-1tb', 'LAC4000100', 'B08VG7VS7F', 'LaCie Rugged SSD', 1000, 'External', 'USB 3.2 Gen 2', 950, 950, 600, 5, 'The Rugged SSD without the Pro - same IP67 orange body but USB-C Gen 2 instead of Thunderbolt. The right compromise for photographers and documentarians whose laptops do not have Thunderbolt anyway and want the ruggedization at a more reasonable price.', NULL, '["IP67 rugged body","1050-class Gen 2 speeds","5-year warranty + Rescue","Detachable USB-C cable"]', '["950 MB/s - slower than full 1050","USB-C only","Premium vs non-rugged SSDs","Bulky"]', 8.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 6, 21, 'LaCie Rugged SSD Portable 2TB', 'lacie-rugged-ssd-portable-2tb', 'LAC4000200', 'B08VG7Q41M', 'LaCie Rugged SSD', 2000, 'External', 'USB 3.2 Gen 2', 950, 950, 1200, 5, 'The 2TB non-Pro Rugged SSD keeps the iconic orange armor but doubles capacity. A frequent pick for outdoor photographers shooting medium-format RAW, where the IP67 rating matters more than the Pro model''s Thunderbolt speeds, and the 950 MB/s USB-C is plenty fast.', NULL, '["2TB + IP67 rugged","5-year Rescue","Detachable USB-C cable","Sustained 950 MB/s for media offload"]', '["950 MB/s - slower than T7","Premium vs non-rugged 2TB","Bulkier than T7","USB-C only"]', 8.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 8, 'Kingston XS2000 Portable 1TB', 'kingston-xs2000-portable-1tb', 'SDSE2000/1TB', 'B09FB1P7LQ', 'Kingston XS2000', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 600, 5, 'A Gen 2x2 portable with 5-year warranty from Kingston. The 5-year warranty is rare at Gen 2x2 pricing and gives the XS2000 a real advantage vs Patriot and Sabrent at this speed tier. 2-meter drop rating but no IP rating.', NULL, '["Gen 2x2 2000 MB/s","5-year warranty","2-meter drop rating","Detachable USB-C cable"]', '["No IP rating","Caps at 1050 on Gen 2 hosts","Sustained writes dip after cache","Premium vs Patriot Evlvr 1TB"]', 8.3, 0, 1, NULL, NULL);
