('portablessds', 5, 8, 'Kingston XS2000 Portable 4TB', 'kingston-xs2000-portable-4tb', 'SDSE2000/4TB', 'B09V3MJN32', 'Kingston XS2000', 4000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 2400, 5, 'A 4TB XS2000 - the budget king at Gen 2x2 4TB. Kingston has priced the XS2000 4TB aggressively vs the Samsung T9 4TB. The T9 has the slightly stronger sustained-write thermal behavior on long transfers but the price gap is meaningful.', NULL, '["4TB Gen 2x2 + 5-year warranty","Budget pricing","2400 TBW endurance","Detachable cable"]', '["No IP rating","Plastic body","Caps at 1050 MB/s on Gen 2 hosts","Conservative sustained writes after cache"]', 8.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
