INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 10, 'ADATA SE800 Portable 2TB', 'adata-se800-portable-2tb', 'ASSE800-2TU32G2-C', 'B08GJKYGCJ', 'ADATA SE800', 2000, 'External', 'USB 3.2 Gen 2', 1000, 950, 1200, 3, 'The 2TB SE800 keeps the same tiny plastic body of the 1TB version -- awwardly small for 2TB. Budget pricing per-TB makes it a value buy for PS5/Xbox cold library expansion, where sustained write speed takes a back seat to capacity-per-dollar.', NULL, '["2TB budget portable","1000 MB/s read","Tiny form factor","USB-C cable included"]', '["Plastic body","3-year warranty","No IP rating","950 MB/s write"]', 7.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
