INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 26, 'Silicon Power PC60 Portable 2TB', 'silicon-power-pc60-portable-2tb', 'SP2TBPC60K', 'B09P3SF1FB', 'Silicon Power PC60', 2000, 'External', 'USB 3.2 Gen 2', 1000, 900, 1200, 3, 'A 2TB budget Gen 2 portable aimed at game-library cold storage for PS5/Xbox. Aggressive pricing makes it competitive against the Seagate One Touch 2TB on sale. Not a drive for sustained-write-heavy creative workflows.', NULL, '["2TB budget Gen 2","1000 MB/s read","Compact profile","USB-C cable included"]', '["900 MB/s write","Plastic body","No IP rating","3-year warranty"]', 7.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 27, 'Transcend ESD310C Portable 1TB', 'transcend-esd310c-portable-1tb', 'TS1TESD310C', 'B0BLNQYTNS', 'Transcend ESD310C', 1000, 'External', 'USB 3.2 Gen 2', 1050, 950, 600, 3, 'A tiny 1050-class Gen 2 portable from a long-established memory brand. The ESD310C is among the smallest 1TB Gen 2 SSDs in retail -- small enough to be lost in a bag. Buy it for the form factor over sustained performance.', NULL, '["1050/950 MB/s","Tiny credit-card footprint","3-year warranty","Rotating cap protects USB-C port"]', '["Plastic body","No IP rating","3-year warranty","Sustained writes dip after cache"]', 7.6, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 27, 'Transcend ESD310C Portable 2TB', 'transcend-esd310c-portable-2tb', 'TS2TESD310C', 'B0C6KB3ZSM', 'Transcend ESD310C', 2000, 'External', 'USB 3.2 Gen 2', 1050, 950, 1200, 3, 'The 2TB ESD310C keeps the same tiny plastic credit-card footprint of the 1TB -- Transcend fits an unusually large stack in an unusually small case. The 2TB cache budget also holds the 950 MB/s write past 200GB on long transfers.', NULL, '["1050/950 MB/s","Tiny footprint","2400 TBW endurance","Rotating cap protects USB-C port"]', '["Plastic body","No IP rating","3-year warranty","Premium vs ADATA SE800 2TB"]', 7.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 28, 'Inland Performance Portable 1TB', 'inland-performance-portable-1tb', 'INP-1TB', 'B0B7CHQ6H5', 'Inland Performance', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 600, 3, 'A MicroCenter house-brand Gen 2x2 portable at aggressive pricing. Built on standard NAND -- not exceptional build but cheap for the speed tier, and easy to find in MicroCenter retail stores.', NULL, '["Gen 2x2 2000 MB/s","MicroCenter-retail pricing","3-year warranty","USB-C cable included"]', '["Plastic body","3-year warranty","No IP rating","Caps at 1050 on Gen 2 hosts"]', 7.7, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 28, 'Inland Performance Portable 2TB', 'inland-performance-portable-2tb', 'INP-2TB', 'B0B7CHRJZV', 'Inland Performance', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 3, 'A 2TB Gen 2x2 portable from Inlands house line. Aggressive pricing vs the brand-name tier -- while MicroCenter regularly stocks them in stores, online stock availability is inconsistent.', NULL, '["Gen 2x2 2000 MB/s","2TB capacity","MicroCenter retail availability","3-year warranty"]', '["Plastic body","No IP rating","Inconsistent online availability","Sustained writes dip after cache"]', 7.8, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 29, 'ORICO UFSD Portable 1TB', 'orico-ufsd-portable-1tb', 'ORICO-UFSD-1T', 'B0CY7P4KQW', 'ORICO UFSD', 1000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 600, 3, 'A newer Amazon-direct Gen 2x2 portable from ORICO. Aggressive sale pricing, aluminum body, full 2000 MB/s rating -- but independent review reports are mixed on sustained writes after SLC cache exhaustion.', NULL, '["Gen 2x2 2000 MB/s","Aggressive Amazon sale pricing","Aluminum body","USB-C cable included"]', '["3-year warranty","No IP rating","Mixed sustained write reviews","Newer market entrant"]', 7.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 29, 'ORICO UFSD Portable 2TB', 'orico-ufsd-portable-2tb', 'ORICO-UFSD-2T', 'B0CY7P4PZ6', 'ORICO UFSD', 2000, 'External', 'USB 3.2 Gen 2x2', 2000, 2000, 1200, 3, 'The 2TB UFSD doubles capacity of the ORICO Gen 2x2 line. Pricing typically tracks the Inland Performance 2TB -- both are house-tier aggressive pills. The aluminum body distinguishes the ORICO visually from the plastic-bodied Inland.', NULL, '["Gen 2x2 2000 MB/s","2TB capacity","Aluminum body","Aggressive pricing"]', '["3-year warranty","No IP rating","Mixed sustained write reviews","Newer brand with thin retail track record"]', 7.5, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 4, 30, 'SSK SHE030 Portable 1TB', 'ssk-she030-portable-1tb', 'SHE030-1T', 'B0CF7Q8HND', 'SSK SHE030', 1000, 'External', 'USB 3.2 Gen 2', 1050, 1000, 600, 3, 'A budget 1050-class Gen 2 portable from SSK. Compatible with PS5 expandable storage (USB cold library) and Xbox cold storage. Aggressive pricing makes it a value-tier option for console-game overflow where peak sustained speed is not critical.', NULL, '["1050 MB/s read","Budget aggressive price","PS5/Xbox cold-library compatible","USB-C cable included"]', '["1000 MB/s write (not full 1050)","3-year warranty","No IP rating","Sustained writes dip after cache"]', 7.4, 0, 1, NULL, NULL);
INSERT INTO products (site_id, category_id, brand_id, name, slug, model, asin, model_family, capacity_gb, form_factor, interface, read_speed_mbps, write_speed_mbps, tbw, warranty_years, description, specifications, pros, cons, overall_score, is_featured, is_active, gtin13, image_url) VALUES
('portablessds', 5, 30, 'SSK PM510 USB4 Portable 1TB', 'ssk-pm510-usb4-portable-1tb', 'PM510-1T', 'B0C7R43F1M', 'SSK PM510 USB4', 1000, 'External', 'USB4', 3200, 2800, 600, 3, 'A USB4 portable at enthusiast-grade specs -- 3200 MB/s read over USB4 / Thunderbolt 4 hosts. The PM510 is one of the more affordable USB4 portables, an entry point for video editors who need Thunderbolt-class speeds but do not want to pay LaCie or OWC premium.', NULL, '["USB4 3200 MB/s","Thunderbolt 4 compatible","Aluminum body","3-year warranty"]', '["3-year warranty (not 5)","Requires USB4/Thunderbolt 4 host","Premium vs Gen 2 drives on USB-C host","Sustained writes dip after cache"]', 8.6, 0, 1, NULL, NULL);
