-- ============================================================================
-- PRICES: One Amazon Special Link per product (tag injected at render time
-- by GeoAffiliateLink; price_cents is 0 because Phase 1 compliance removed
-- all primary visible price display).
-- We use INSERT INTO ... SELECT to pair the price row with the product_id
-- at execution time, building the affiliate_url from the product''s asin.
-- The NOT EXISTS clause makes this idempotent — re-running the seed will
-- not create duplicate Amazon Special Link rows for products that already
-- have one.
-- ============================================================================

SELECT id, 'Amazon', 'US', 'new', 0, 'USD',
       'https://www.amazon.com/dp/' || asin,
       'manual', 1, datetime('now')
FROM products
WHERE asin IS NOT NULL
  AND asin <> ''
  AND NOT EXISTS (
    SELECT 1 FROM prices p
    WHERE p.product_id = products.id
      AND p.retailer = 'Amazon'
      AND p.marketplace = 'US'
      AND p.condition = 'new'
  );
